#!/usr/bin/env node
import process from "node:process";
import { detectColorLevel, createColors, ColorLevel } from "../src/index.js";

const LEVEL_NAMES = {
  [ColorLevel.NONE]: "none",
  [ColorLevel.BASIC]: "basic (16 colors)",
  [ColorLevel.COLORS_256]: "256 colors",
  [ColorLevel.TRUECOLOR]: "truecolor",
};

const HELP = `Usage: color-cli [options] [name]

Print a greeting using color only when the terminal supports it.

Options:
  --info      Show detected color support and exit
  -h, --help  Show this help

Environment:
  NO_COLOR     Disable color when set to a non-empty value
  FORCE_COLOR  Force color on (0 disables, 1-3 select a level)
`;

function main(argv) {
  if (argv.includes("--help") || argv.includes("-h")) {
    process.stdout.write(HELP);
    return 0;
  }

  const level = detectColorLevel();

  if (argv.includes("--info")) {
    process.stdout.write(`color support: ${level > 0 ? "yes" : "no"} (${LEVEL_NAMES[level]})\n`);
    return 0;
  }

  const colors = createColors(level);
  const name = argv.find((arg) => !arg.startsWith("-")) ?? "world";
  const status = level > 0 ? colors.green("enabled") : colors.dim("disabled");

  process.stdout.write(
    `${colors.green("Hello")}, ${colors.bold(name)}! ${colors.cyan("Terminal color is")} ${status}.\n`,
  );
  return 0;
}

process.exitCode = main(process.argv.slice(2));

import test from "node:test";
import assert from "node:assert/strict";
import { detectColorLevel, supportsColor, ColorLevel } from "../src/supports-color.js";

const tty = (depth) => ({ isTTY: true, getColorDepth: () => depth });
const pipe = { isTTY: false };

test("disables color for non-TTY streams", () => {
  assert.equal(detectColorLevel({ env: {}, stream: pipe }), ColorLevel.NONE);
});

test("detects truecolor from stream depth", () => {
  assert.equal(detectColorLevel({ env: {}, stream: tty(24) }), ColorLevel.TRUECOLOR);
  assert.equal(detectColorLevel({ env: {}, stream: tty(8) }), ColorLevel.COLORS_256);
  assert.equal(detectColorLevel({ env: {}, stream: tty(4) }), ColorLevel.BASIC);
  assert.equal(detectColorLevel({ env: {}, stream: tty(1) }), ColorLevel.NONE);
});

test("falls back to basic color for a plain TTY", () => {
  assert.equal(detectColorLevel({ env: {}, stream: { isTTY: true } }), ColorLevel.BASIC);
});

test("honors NO_COLOR when non-empty", () => {
  assert.equal(detectColorLevel({ env: { NO_COLOR: "1" }, stream: tty(24) }), ColorLevel.NONE);
});

test("ignores empty NO_COLOR", () => {
  assert.equal(detectColorLevel({ env: { NO_COLOR: "" }, stream: tty(24) }), ColorLevel.TRUECOLOR);
});

test("honors TERM=dumb", () => {
  assert.equal(detectColorLevel({ env: { TERM: "dumb" }, stream: tty(24) }), ColorLevel.NONE);
});

test("FORCE_COLOR overrides NO_COLOR and non-TTY", () => {
  assert.equal(
    detectColorLevel({ env: { FORCE_COLOR: "1", NO_COLOR: "1" }, stream: pipe }),
    ColorLevel.BASIC,
  );
  assert.equal(detectColorLevel({ env: { FORCE_COLOR: "3" }, stream: pipe }), ColorLevel.TRUECOLOR);
});

test("FORCE_COLOR=0 disables color on a TTY", () => {
  assert.equal(detectColorLevel({ env: { FORCE_COLOR: "0" }, stream: tty(24) }), ColorLevel.NONE);
});

test("FORCE_COLOR with an empty value means basic color", () => {
  assert.equal(detectColorLevel({ env: { FORCE_COLOR: "" }, stream: pipe }), ColorLevel.BASIC);
});

test("supportsColor checks the requested threshold", () => {
  assert.equal(supportsColor(2, { env: { FORCE_COLOR: "1" }, stream: pipe }), true);
  assert.equal(supportsColor(256, { env: { FORCE_COLOR: "1" }, stream: pipe }), false);
  assert.equal(supportsColor(256, { env: { FORCE_COLOR: "3" }, stream: pipe }), true);
});

import test from "node:test";
import assert from "node:assert/strict";
import { createColors } from "../src/colors.js";
import { ColorLevel } from "../src/supports-color.js";

test("formatters are identity functions when color is disabled", () => {
  const colors = createColors(ColorLevel.NONE);
  assert.equal(colors.enabled, false);
  assert.equal(colors.red("hi"), "hi");
  assert.equal(colors.rgb(255, 0, 0, "hi"), "hi");
  assert.equal(colors.ansi256(196, "hi"), "hi");
});

test("basic formatters wrap text in ANSI codes", () => {
  const colors = createColors(ColorLevel.BASIC);
  assert.equal(colors.red("hi"), "\u001b[31mhi\u001b[39m");
  assert.equal(colors.bold("hi"), "\u001b[1mhi\u001b[22m");
});

test("truecolor formatter requires level 3", () => {
  const basic = createColors(ColorLevel.BASIC);
  assert.equal(basic.rgb(255, 0, 0, "hi"), "hi");

  const truecolor = createColors(ColorLevel.TRUECOLOR);
  assert.equal(truecolor.rgb(255, 0, 0, "hi"), "\u001b[38;2;255;0;0mhi\u001b[39m");
});

test("ansi256 formatter requires at least level 2", () => {
  const basic = createColors(ColorLevel.BASIC);
  assert.equal(basic.ansi256(196, "hi"), "hi");

  const colors = createColors(ColorLevel.COLORS_256);
  assert.equal(colors.ansi256(196, "hi"), "\u001b[38;5;196mhi\u001b[39m");
});

test("empty strings are left untouched", () => {
  const colors = createColors(ColorLevel.TRUECOLOR);
  assert.equal(colors.red(""), "");
});
